var loadAnthropicModels = async (engineConfig, computerInfo = null) => {
  const anthropic = new anthropic_default(engineConfig, computerInfo);
  let metas = [];
  try {
    metas = await anthropic.getModels();
  } catch (error) {
    console.error("Error listing Anthropic models:", error);
  }
  if (!metas) {
    return null;
  }
  const models = metas.map((m) => ({
    id: m.id,
    name: m.display_name,
    capabilities: anthropic.getModelCapabilities(m),
    meta: m
  })).sort((a, b) => b.meta.created_at.localeCompare(a.meta.created_at));
  const imageModels = [];
  const videoModels = [];
  const embeddingModels = [];
  const computerModels = models.filter((model) => anthropic.isComputerUseModel(model.id));
  const chatModels = models.filter(
    (model) => !imageModels.includes(model) && !videoModels.includes(model) && !embeddingModels.includes(model) && !computerModels.includes(model)
  );
  return {
    chat: chatModels,
    image: imageModels,
    video: videoModels,
    embedding: embeddingModels,
    computer: computerModels
  };
};
